<?php require 'header.php';$s=db()->prepare('SELECT * FROM admins WHERE id=?');$s->execute([$_SESSION['admin_id']]);$admin=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);if($name&&$email){db()->prepare('UPDATE admins SET full_name=?,email=? WHERE id=?')->execute([$name,$email,$_SESSION['admin_id']]);$_SESSION['admin_name']=$name;flash('success','Profile updated.');header('Location: profile.php');exit;}}?><div class="admin-title"><p>ACCOUNT</p><h2>Admin profile</h2></div><form class="admin-form profile" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Full name<input required name="full_name" value="<?=e($admin['full_name'])?>"></label><label>Email<input required type="email" name="email" value="<?=e($admin['email'])?>"></label><button class="save">Save profile</button></form><?php require 'footer.php'; ?>
